import{_ as s,l as t,o as e,c,v as r,p as o,x as i,d as l,i as n,S as m}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"discard 与 TRIM","description":"","frontmatter":{"title":"discard 与 TRIM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/discard-trim.md","filePath":"cs/discard-trim.md","lastUpdated":1789023840000}'),p={name:"cs/discard-trim.md"};function T(f,a,h,_,u,M){const d=t("Mermaid");return e(),c("div",null,[a[1]||(a[1]=r('<h1 id="discard-与-trim" tabindex="-1">discard 与 TRIM <a class="header-anchor" href="#discard-与-trim" aria-label="Permalink to &quot;discard 与 TRIM&quot;">​</a></h1><div class="epigraph"><p>discard/TRIM 告诉闪存哪些 LBA 不再包含有效数据，FTL 才好在垃圾回收时不搬它们。</p><footer>—— 据 ATA TRIM / NVMe deallocate；Linux mount discard 与 fstrim 文档</footer></div><p><a href="/cs/write-barrier-fua">上一课</a>管「必须留下的写」。删除文件、<a href="/cs/sparse-files">穿孔</a>、<a href="/cs/thin-provisioning">thin</a> 还块之后，SSD 若仍当有效，GC 会搬垃圾。缺口是 <strong>discard</strong>：FS 空闲 → 块层 TRIM → 设备 deallocate。存储栈课序在此收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>POSIX <code>unlink</code> 只改 FS 元数据。SSD 的 FTL 不知 inode。<code>FITRIM</code>/<code>fstrim</code> 或挂载 <code>discard</code>：对空闲范围发 discard bio。缺口：实时 discard 可能拖慢删除；批量 fstrim 更常见；安全上 TRIM 可能向下层泄露空闲图（<a href="/cs/dm-crypt">dm-crypt</a> 有 <code>allow_discards</code> 旋钮）；RAID/thin 必须把 discard 正确 remap，否则剪错盘。本课不把 zoned 复位当 TRIM 的同义词，只点相近。</p><p><span class="marginnote">NVMe Dataset Management / deallocate、SCSI UNMAP 是同一意图的命令。不支持则 FS 仍能工作，只是写放大变差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>e2fsck 不管 TRIM。运行时：<code>fstrim /</code> 查询 FS 空闲 extent，发 discard。thin：discard 取消映射并可能对池成员再 TRIM。对照 <a href="/cs/fsck">fsck</a>：fsck 重建位图后应再 trim，以免位图与 FTL 长期偏离。对照预读：discard 不是读。</p>',8)),(e(),o(m,null,{default:i(()=>[n(d,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22FS%20%E7%A9%BA%E9%97%B2%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20DC%5B%22discard%20bio%22%5D%0A%20%20DC%20--%3E%20MAP%5B%22dm%2Fmd%20remap%22%5D%0A%20%20MAP%20--%3E%20CMD%5B%22TRIM%2Fdeallocate%22%5D%0A%20%20CMD%20--%3E%20FTL%5B%22FTL%20%E4%B8%8D%E6%90%AC%E8%BF%99%E4%BA%9B%E9%A1%B5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TRIM 把 FS 空闲信息推到 FTL，是闪存上「诚实的空闲」。它不保证立刻擦除（安全擦除是另一命令），也不替代加密。不要写成硬件寿命营销。与配额：discard 后用量下降，记账要跟穿孔一样减。</p><p>网络下一单元：这些块 I/O 直觉有一部分会在网卡队列上重现——但对象换成包。</p><p>实现上：实时 discard 把删除变成同步设备命令，USB 桥接上会卡。fstrim.timer 批量做是发行版默认。加密盘默认不传 discard，以免泄露空闲图。 读法上只引用<a href="/cs/write-barrier-fua">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>discard 与 TRIM</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每次厂商的 TRIM 队列深度quirk。不保证 USB 桥接转发 UNMAP。文件系统与存储栈到此接到设备介质。下一单元从套接字缓冲的内核对象开始：sk_buff。</p><p>版本字段会变，课序钉的是机制对象「discard 与 TRIM」，不是某一主线内核的结构体名。 后课默认：空闲块可通知闪存。包在内核里的载体，下一课 sk_buff。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>discard/TRIM 把 FS 空闲告诉 FTL，降低写放大。</li><li>批量 fstrim 往往优于实时 discard；加密与 RAID 要小心传递。</li><li>网络栈从 sk_buff 起。</li><li>出处：ATA TRIM；NVMe；Linux fstrim；<em>OSTEP</em> SSD 章。</li></ul>',11))])}const A=s(p,[["render",T]]);export{I as __pageData,A as default};
